    readonly "settings.magicPrompts.page.group.sessionExplore.title": "Recorrido del código";
    readonly "settings.magicPrompts.page.group.sessionExplore.description": "Prompts usados por el comando /explore: mensaje visible del usuario + instrucciones ocultas. Investiga el repositorio y ofrece una orientación estructurada — la visión general, los módulos principales, cómo se conectan y por dónde empezar — en lugar de un listado archivo por archivo.";
    readonly "settings.magicPrompts.page.group.sessionWorkspaceReview.description": "Prompts usados por el comando /workspace-review: mensaje visible del usuario + instrucciones ocultas. Revisa el diff del espacio de trabajo: si logra su intención y si es correcto y adecuado, clasificando los hallazgos por severidad. Las instrucciones también guían las sesiones de revisión, incluido el bucle de revisión automática.";
    readonly "settings.magicPrompts.page.group.sessionFeaturePlan.title": "Planificación de funciones";
    readonly "settings.magicPrompts.page.group.sessionFeaturePlan.description": "Prompts usados por el comando /plan-feature: mensaje visible del usuario + instrucciones ocultas. Ejecuta un diálogo guiado que investiga el código y hace preguntas aclaratorias en lotes pequeños antes de producir un plan de implementación.";
    readonly "settings.magicPrompts.page.group.sessionCatchUp.title": "Ponerse al día";
    readonly "settings.magicPrompts.page.group.sessionCatchUp.description": "Prompts usados por el comando /catch-up: mensaje visible del usuario + instrucciones ocultas. Construye contexto según la rama — los commits de la rama, su PR y el trabajo sin confirmar juntos — para entender qué estabas haciendo, y luego da un resumen fácil de digerir y un siguiente paso centrado en el producto.";
    readonly "settings.magicPrompts.page.group.sessionDebug.title": "Depuración";
    readonly "settings.magicPrompts.page.group.sessionDebug.description": "Prompts usados por el comando /debug: mensaje visible del usuario + instrucciones ocultas. Ejecuta una investigación guiada de la causa raíz: captura el síntoma, formula hipótesis, las verifica contra el código y confirma la causa antes de proponer una solución.";
    readonly "settings.magicPrompts.page.group.sessionWeigh.title": "Comparar enfoques";
    readonly "settings.magicPrompts.page.group.sessionWeigh.description": "Prompts usados por el comando /weigh: mensaje visible del usuario + instrucciones ocultas. Investiga el código y luego presenta 2-3 enfoques distintos con sus ventajas y desventajas y una recomendación, sin escribir un plan ni código.";
    readonly "settings.magicPrompts.page.group.sessionFusion.title": "Fusion";
